// BackendServiceHandler is an implementation of the backend.v1.BackendService service.
type BackendServiceHandler interface {
	// Room
	// Rooms returns the daemon's cached joined rooms.
	Rooms(context.Context, *connect.Request[v1.RoomsRequest]) (*connect.Response[v1.RoomsResponse], error)
	// RefreshRooms fetches from the homeserver, updates the cache, and returns the fresh
	// list.
	RefreshRooms(context.Context, *connect.Request[v1.RefreshRoomsRequest]) (*connect.Response[v1.RefreshRoomsResponse], error)
	// MarkRead sends an m.read receipt, advancing our read marker.
	MarkRead(context.Context, *connect.Request[v1.MarkReadRequest]) (*connect.Response[v1.MarkReadResponse], error)
	// MarkRoomsRead marks whole rooms read without opening them, receipting the newest
	// event the daemon knows of in each.
	MarkRoomsRead(context.Context, *connect.Request[v1.MarkRoomsReadRequest]) (*connect.Response[v1.MarkRoomsReadResponse], error)
	// MarkRoomUnread sets or clears m.marked_unread on a room, which every client on the
	// account then sees.
	MarkRoomUnread(context.Context, *connect.Request[v1.MarkRoomUnreadRequest]) (*connect.Response[v1.MarkRoomUnreadResponse], error)
	// StarMessage adds or removes one message's private bookmark.
	StarMessage(context.Context, *connect.Request[v1.StarMessageRequest]) (*connect.Response[v1.StarMessageResponse], error)
	// StarredIn lists the starred messages of one room, from the cache.
	StarredIn(context.Context, *connect.Request[v1.StarredInRequest]) (*connect.Response[v1.StarredInResponse], error)
	// CanonicalParent resolves the space a room lives in (canonical m.space.parent).
	CanonicalParent(context.Context, *connect.Request[v1.CanonicalParentRequest]) (*connect.Response[v1.CanonicalParentResponse], error)
	// LastMessages is when each room last had a message, for ordering the list by
	// activity.
	LastMessages(context.Context, *connect.Request[v1.LastMessagesRequest]) (*connect.Response[v1.LastMessagesResponse], error)
	// SpamRooms lists the rooms a spam filter caught, with the rule and the filter that
	// caught each.
	SpamRooms(context.Context, *connect.Request[v1.SpamRoomsRequest]) (*connect.Response[v1.SpamRoomsResponse], error)
	// MarkSpam records a verdict on one room, or clears it.
	MarkSpam(context.Context, *connect.Request[v1.MarkSpamRequest]) (*connect.Response[v1.MarkSpamResponse], error)
	// Space
	// Spaces returns the cached spaces, each with its direct child rooms.
	Spaces(context.Context, *connect.Request[v1.SpacesRequest]) (*connect.Response[v1.SpacesResponse], error)
	// RefreshSpaces fetches the hierarchy from the homeserver and caches it.
	RefreshSpaces(context.Context, *connect.Request[v1.RefreshSpacesRequest]) (*connect.Response[v1.RefreshSpacesResponse], error)
	// AddToSpace files a room into a space (m.space.child plus a non-canonical
	// m.space.parent).
	AddToSpace(context.Context, *connect.Request[v1.AddToSpaceRequest]) (*connect.Response[v1.AddToSpaceResponse], error)
	// RemoveFromSpace takes a room back out, emptying both events AddToSpace wrote.
	RemoveFromSpace(context.Context, *connect.Request[v1.RemoveFromSpaceRequest]) (*connect.Response[v1.RemoveFromSpaceResponse], error)
	// Timeline
	// CachedTimeline returns a room's most recent cached messages for instant display on
	// entry.
	CachedTimeline(context.Context, *connect.Request[v1.CachedTimelineRequest]) (*connect.Response[v1.CachedTimelineResponse], error)
	// Timeline fetches one page of history from the homeserver, older-first.
	Timeline(context.Context, *connect.Request[v1.TimelineRequest]) (*connect.Response[v1.TimelineResponse], error)
	// MessageHistory is every version of one message, from the cache and from the server
	// together.
	MessageHistory(context.Context, *connect.Request[v1.MessageHistoryRequest]) (*connect.Response[v1.MessageHistoryResponse], error)
	// FetchEvent fetches one event by ID — a thread root, or a reply target, that is
	// older than the room's cached window.
	FetchEvent(context.Context, *connect.Request[v1.FetchEventRequest]) (*connect.Response[v1.FetchEventResponse], error)
	// Send posts a message, with its mentions and its reply target.
	Send(context.Context, *connect.Request[v1.SendRequest]) (*connect.Response[v1.SendResponse], error)
	// Redact removes a message's content.
	Redact(context.Context, *connect.Request[v1.RedactRequest]) (*connect.Response[v1.RedactResponse], error)
	// SendFile uploads a file and posts it, encrypting it first where the room is.
	SendFile(context.Context, *connect.Request[v1.SendFileRequest]) (*connect.Response[v1.SendFileResponse], error)
	// SendTyping tells a room you are typing, or that you have stopped.
	SendTyping(context.Context, *connect.Request[v1.SendTypingRequest]) (*connect.Response[v1.SendTypingResponse], error)
	// Unread
	// CachedUnread returns every room's cached unread state for instant badges.
	CachedUnread(context.Context, *connect.Request[v1.CachedUnreadRequest]) (*connect.Response[v1.CachedUnreadResponse], error)
	// UnreadStream streams per-room unread updates as sync ingests them.
	UnreadStream(context.Context, *connect.Request[v1.UnreadStreamRequest], *connect.ServerStream[v1.UnreadStreamResponse]) error
	// Thread
	// ListThreads returns a room's threads, newest activity first, with what is unread in
	// each — for a room whether or not it is open.
	ListThreads(context.Context, *connect.Request[v1.ListThreadsRequest]) (*connect.Response[v1.ListThreadsResponse], error)
	// ThreadPage fetches one page of a thread's history from the homeserver, older than
	// what is cached.
	ThreadPage(context.Context, *connect.Request[v1.ThreadPageRequest]) (*connect.Response[v1.ThreadPageResponse], error)
	// MarkThreadRead marks one thread read up to an event.
	MarkThreadRead(context.Context, *connect.Request[v1.MarkThreadReadRequest]) (*connect.Response[v1.MarkThreadReadResponse], error)
	// Reaction
	// CachedReactions returns a room's cached reactions for instant display.
	CachedReactions(context.Context, *connect.Request[v1.CachedReactionsRequest]) (*connect.Response[v1.CachedReactionsResponse], error)
	// Reactions streams adds and removals as sync delivers them.
	Reactions(context.Context, *connect.Request[v1.ReactionsRequest], *connect.ServerStream[v1.ReactionsResponse]) error
	// SendReaction posts an m.reaction annotating a message.
	SendReaction(context.Context, *connect.Request[v1.SendReactionRequest]) (*connect.Response[v1.SendReactionResponse], error)
	// ReactionRefusals returns what has been learned about the emoji bridged networks
	// refuse as reactions.
	ReactionRefusals(context.Context, *connect.Request[v1.ReactionRefusalsRequest]) (*connect.Response[v1.ReactionRefusalsResponse], error)
	// RecordReactionRefusal notes one the client observed itself.
	RecordReactionRefusal(context.Context, *connect.Request[v1.RecordReactionRefusalRequest]) (*connect.Response[v1.RecordReactionRefusalResponse], error)
	// Emoji
	// RecordEmoji notes one emoji the user chose, so the ranking learns from it.
	RecordEmoji(context.Context, *connect.Request[v1.RecordEmojiRequest]) (*connect.Response[v1.RecordEmojiResponse], error)
	// EmojiScores weighs each emoji's usage for one room, for ordering the panel, over
	// the rooms the scope admits.
	EmojiScores(context.Context, *connect.Request[v1.EmojiScoresRequest]) (*connect.Response[v1.EmojiScoresResponse], error)
	// Media
	// LoadImage resolves a message's media from cache or the homeserver, decrypting it in
	// an encrypted room, and returns the raw bytes.
	LoadImage(context.Context, *connect.Request[v1.LoadImageRequest]) (*connect.Response[v1.LoadImageResponse], error)
	// Member
	// Members returns a room's cached members, ordered by display name.
	Members(context.Context, *connect.Request[v1.MembersRequest]) (*connect.Response[v1.MembersResponse], error)
	// RefreshMembers fetches membership from the homeserver and replaces the cache.
	RefreshMembers(context.Context, *connect.Request[v1.RefreshMembersRequest]) (*connect.Response[v1.RefreshMembersResponse], error)
	// MentionCandidates ranks a room's members for the mention dropdown.
	MentionCandidates(context.Context, *connect.Request[v1.MentionCandidatesRequest]) (*connect.Response[v1.MentionCandidatesResponse], error)
	// SearchSenders ranks the people who have posted in a set of rooms, for the search
	// box's `from:` filter.
	SearchSenders(context.Context, *connect.Request[v1.SearchSendersRequest]) (*connect.Response[v1.SearchSendersResponse], error)
	// DirectCandidates ranks the people this account has no direct message with.
	DirectCandidates(context.Context, *connect.Request[v1.DirectCandidatesRequest]) (*connect.Response[v1.DirectCandidatesResponse], error)
	// SenderSlots returns a room's remembered color slots.
	SenderSlots(context.Context, *connect.Request[v1.SenderSlotsRequest]) (*connect.Response[v1.SenderSlotsResponse], error)
	// SaveSenderSlots records the ones a client has assigned.
	SaveSenderSlots(context.Context, *connect.Request[v1.SaveSenderSlotsRequest]) (*connect.Response[v1.SaveSenderSlotsResponse], error)
	// Membership
	// CachedInvites returns the cached pending invitations.
	CachedInvites(context.Context, *connect.Request[v1.CachedInvitesRequest]) (*connect.Response[v1.CachedInvitesResponse], error)
	// Invites streams the complete set of pending invitations on each change.
	Invites(context.Context, *connect.Request[v1.InvitesRequest], *connect.ServerStream[v1.InvitesResponse]) error
	// JoinRoom joins a room by ID or alias, which is also how an invite is accepted, and
	// returns the ID joined.
	JoinRoom(context.Context, *connect.Request[v1.JoinRoomRequest]) (*connect.Response[v1.JoinRoomResponse], error)
	// LeaveRoom leaves a room.
	LeaveRoom(context.Context, *connect.Request[v1.LeaveRoomRequest]) (*connect.Response[v1.LeaveRoomResponse], error)
	// Deciding who else is in a room.
	CreateRoom(context.Context, *connect.Request[v1.CreateRoomRequest]) (*connect.Response[v1.CreateRoomResponse], error)
	InviteUser(context.Context, *connect.Request[v1.InviteUserRequest]) (*connect.Response[v1.InviteUserResponse], error)
	KickUser(context.Context, *connect.Request[v1.KickUserRequest]) (*connect.Response[v1.KickUserResponse], error)
	BanUser(context.Context, *connect.Request[v1.BanUserRequest]) (*connect.Response[v1.BanUserResponse], error)
	UnbanUser(context.Context, *connect.Request[v1.UnbanUserRequest]) (*connect.Response[v1.UnbanUserResponse], error)
	// Search
	// SearchMessages finds cached messages matching query, newest first.
	SearchMessages(context.Context, *connect.Request[v1.SearchMessagesRequest]) (*connect.Response[v1.SearchMessagesResponse], error)
	// ModelTask asks the optional language-model layer for one thing.
	ModelTask(context.Context, *connect.Request[v1.ModelTaskRequest]) (*connect.Response[v1.ModelTaskResponse], error)
	// ReplaceDraft stores one room's half-written message (or removes it when there is
	// nothing left worth keeping), only while the stored draft is still the one the
	// writer read, so neither writer (TUI, kith-mcp) drops the other's words.
	ReplaceDraft(context.Context, *connect.Request[v1.ReplaceDraftRequest]) (*connect.Response[v1.ReplaceDraftResponse], error)
	Drafts(context.Context, *connect.Request[v1.DraftsRequest]) (*connect.Response[v1.DraftsResponse], error)
	// Seat is the one window the daemon serves (kith-mcp and one-shot commands take
	// none). Opening the stream asks for it; keeping it open keeps it, and a window
	// that closes or dies frees it. See SeatRequest.force and SeatResponse.
	Seat(context.Context, *connect.Request[v1.SeatRequest], *connect.ServerStream[v1.SeatResponse]) error
	// PairWhatsApp links one configured [[whatsapp.account]] to kith as a WhatsApp
	// linked device: the stream carries the code to type on the phone, then the
	// account's ID once the phone accepts it. A failure ends the stream with an error.
	PairWhatsApp(context.Context, *connect.Request[v1.PairWhatsAppRequest], *connect.ServerStream[v1.PairWhatsAppResponse]) error
	// RoomsWith finds the rooms a set of people are **all** in, most recently active
	// first.
	RoomsWith(context.Context, *connect.Request[v1.RoomsWithRequest]) (*connect.Response[v1.RoomsWithResponse], error)
	// RoomEncryption says which of these rooms are end-to-end encrypted.
	RoomEncryption(context.Context, *connect.Request[v1.RoomEncryptionRequest]) (*connect.Response[v1.RoomEncryptionResponse], error)
	// MessagesAround is one message with its neighbours.
	MessagesAround(context.Context, *connect.Request[v1.MessagesAroundRequest]) (*connect.Response[v1.MessagesAroundResponse], error)
	// CompleteWord finishes a partly typed word from what has been said in scope, ranked,
	// then tops the list up from the installed word-frequency list for the language the
	// prefix is in.
	CompleteWord(context.Context, *connect.Request[v1.CompleteWordRequest]) (*connect.Response[v1.CompleteWordResponse], error)
	// Sync
	// Messages streams incoming room messages for as long as the client keeps the stream
	// open.
	Messages(context.Context, *connect.Request[v1.MessagesRequest], *connect.ServerStream[v1.MessagesResponse]) error
	// Activity streams typing and other people's read receipts.
	ActivityStream(context.Context, *connect.Request[v1.ActivityStreamRequest], *connect.ServerStream[v1.ActivityStreamResponse]) error
	// Follow hands a matrix URI to whichever client is attached — the desktop clicked a
	// link, and the running TUI is what can go there.
	Follow(context.Context, *connect.Request[v1.FollowRequest]) (*connect.Response[v1.FollowResponse], error)
	// FollowStream is the receiving end, held open by the TUI.
	FollowStream(context.Context, *connect.Request[v1.FollowStreamRequest], *connect.ServerStream[v1.FollowStreamResponse]) error
	// Verification
	// Verifications streams verification steps (request, SAS, done, canceled).
	Verifications(context.Context, *connect.Request[v1.VerificationsRequest], *connect.ServerStream[v1.VerificationsResponse]) error
	// StartVerification asks this account's other devices to verify this one.
	StartVerification(context.Context, *connect.Request[v1.StartVerificationRequest]) (*connect.Response[v1.StartVerificationResponse], error)
	// AcceptVerification accepts an incoming request, advancing toward the SAS
	// comparison.
	AcceptVerification(context.Context, *connect.Request[v1.AcceptVerificationRequest]) (*connect.Response[v1.AcceptVerificationResponse], error)
	// ConfirmSAS confirms the displayed short authentication string matches.
	ConfirmSAS(context.Context, *connect.Request[v1.ConfirmSASRequest]) (*connect.Response[v1.ConfirmSASResponse], error)
	// CancelVerification aborts an in-progress verification.
	CancelVerification(context.Context, *connect.Request[v1.CancelVerificationRequest]) (*connect.Response[v1.CancelVerificationResponse], error)
	// Maintenance
	// Status reports whether the daemon is ready to serve, and why not if it isn't.
	Status(context.Context, *connect.Request[v1.StatusRequest]) (*connect.Response[v1.StatusResponse], error)
	// ClearCache empties the local cache.
	ClearCache(context.Context, *connect.Request[v1.ClearCacheRequest]) (*connect.Response[v1.ClearCacheResponse], error)
	// RestoreKeyBackup imports the server-side room-key backup, so encrypted history from
	// before this device joined decrypts.
	RestoreKeyBackup(context.Context, *connect.Request[v1.RestoreKeyBackupRequest]) (*connect.Response[v1.RestoreKeyBackupResponse], error)
	// ExportRoomKeys returns this device's room keys as an encrypted export file, for an
	// account with no server-side backup to restore from.
	ExportRoomKeys(context.Context, *connect.Request[v1.ExportRoomKeysRequest]) (*connect.Response[v1.ExportRoomKeysResponse], error)
	// ImportRoomKeys adds the sessions in such a file to this device's store.
	ImportRoomKeys(context.Context, *connect.Request[v1.ImportRoomKeysRequest]) (*connect.Response[v1.ImportRoomKeysResponse], error)
	// BootstrapKeyBackup sets up cross-signing, secret storage and key backup.
	BootstrapKeyBackup(context.Context, *connect.Request[v1.BootstrapKeyBackupRequest]) (*connect.Response[v1.BootstrapKeyBackupResponse], error)
	// DetectLanguages counts the scripts in the cached corpus and returns the spelling
	// dictionaries worth installing for them.
	DetectLanguages(context.Context, *connect.Request[v1.DetectLanguagesRequest]) (*connect.Response[v1.DetectLanguagesResponse], error)
	// InstallDictionary fetches one dictionary by tag, verifying it against the hash the
	// manifest pinned.
	InstallDictionary(context.Context, *connect.Request[v1.InstallDictionaryRequest]) (*connect.Response[v1.InstallDictionaryResponse], error)
	// InstallFrequencies fetches one language's word counts, which is what the rare-word
	// check reads.
	InstallFrequencies(context.Context, *connect.Request[v1.InstallFrequenciesRequest]) (*connect.Response[v1.InstallFrequenciesResponse], error)
	// DetectModel answers whether the local completion model is worth offering.
	DetectModel(context.Context, *connect.Request[v1.DetectModelRequest]) (*connect.Response[v1.DetectModelResponse], error)
	// InstallModel fetches the weights by tag, verifying them against the hash the
	// manifest pinned, and points the running layer at them.
	InstallModel(context.Context, *connect.Request[v1.InstallModelRequest]) (*connect.Response[v1.InstallModelResponse], error)
	// CheckSpelling returns the words in a draft the engine does not accept.
	CheckSpelling(context.Context, *connect.Request[v1.CheckSpellingRequest]) (*connect.Response[v1.CheckSpellingResponse], error)
	// LearnWord teaches the engine a word it rejected.
	LearnWord(context.Context, *connect.Request[v1.LearnWordRequest]) (*connect.Response[v1.LearnWordResponse], error)
	// AllowRareWord stops the rare-word hint firing on one word, for good.
	AllowRareWord(context.Context, *connect.Request[v1.AllowRareWordRequest]) (*connect.Response[v1.AllowRareWordResponse], error)
	// Notification
	// SetDND puts one temporary rule in force, replacing any rule naming the same thing
	// (the same match and sender).
	SetDND(context.Context, *connect.Request[v1.SetDNDRequest]) (*connect.Response[v1.SetDNDResponse], error)
	// ClearDND lifts one temporary rule, or all of them.
	ClearDND(context.Context, *connect.Request[v1.ClearDNDRequest]) (*connect.Response[v1.ClearDNDResponse], error)
	// DND reports the temporary rules in force.
	DND(context.Context, *connect.Request[v1.DNDRequest]) (*connect.Response[v1.DNDResponse], error)
	// ReloadConfig re-reads the configuration file the daemon was started with, and
	// returns the parse error if it will not load — leaving the running configuration
	// untouched.
	ReloadConfig(context.Context, *connect.Request[v1.ReloadConfigRequest]) (*connect.Response[v1.ReloadConfigResponse], error)
	// Schedule
	// Schedule queues a message.
	Schedule(context.Context, *connect.Request[v1.ScheduleRequest]) (*connect.Response[v1.ScheduleResponse], error)
	// ScheduledMessages is the whole queue, every room, soonest first.
	ScheduledMessages(context.Context, *connect.Request[v1.ScheduledMessagesRequest]) (*connect.Response[v1.ScheduledMessagesResponse], error)
	// CancelScheduled drops one pending message.
	CancelScheduled(context.Context, *connect.Request[v1.CancelScheduledRequest]) (*connect.Response[v1.CancelScheduledResponse], error)
}

